import{_ as i,C as s,o as t,c as n,a2 as a,b as l,w as r,a as d,E as c,a3 as m}from"./chunks/framework.O93z6AWZ.js";const v=JSON.parse('{"title":"Topic 2.2/2.3 — Fundus Imaging (DR/Glaucoma)","description":"","frontmatter":{"title":"Topic 2.2/2.3 — Fundus Imaging (DR/Glaucoma)"},"headers":[],"relativePath":"en/du_an/day_mat.md","filePath":"en/du_an/day_mat.md"}'),u={name:"en/du_an/day_mat.md"};function h(g,e,p,b,y,f){const o=s("Mermaid");return t(),n("div",null,[e[1]||(e[1]=a('<h1 id="topics-2-2-2-3-diabetic-retinopathy-glaucoma-from-fundus-images" tabindex="-1">Topics 2.2 &amp; 2.3: Diabetic Retinopathy &amp; Glaucoma from Fundus Images <a class="header-anchor" href="#topics-2-2-2-3-diabetic-retinopathy-glaucoma-from-fundus-images" aria-label="Permalink to &quot;Topics 2.2 &amp; 2.3: Diabetic Retinopathy &amp; Glaucoma from Fundus Images&quot;">​</a></h1><p><strong>Topic group:</strong> 2. Medical Imaging (Fundus/Dermatology) · <strong>Status:</strong> ✅ Starter literature complete · ⏳ Workflow/timeline per the common template</p><div class="tip custom-block"><p class="custom-block-title">📥 Full documentation on GitHub</p><p>Raw data and detailed source code are kept <strong>Private</strong> on the department&#39;s GitHub repository (so students complete the work themselves). This page gives you the essential information to get started.</p></div><p>Read the <strong><a href="/hmyt-book/en/course_project">Management Framework &amp; Rubric</a></strong> first.</p><hr><h2 id="_1-problem-statement" tabindex="-1">1. Problem statement <a class="header-anchor" href="#_1-problem-statement" aria-label="Permalink to &quot;1. Problem statement&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Research question</strong></td><td>Grade Diabetic Retinopathy severity, or measure the Cup-to-Disc ratio (glaucoma screening), from fundus photographs using deep learning, with explainability (XAI)</td></tr><tr><td><strong>Input (X)</strong></td><td>Fundus photograph</td></tr><tr><td><strong>Output (Y)</strong></td><td>Topic 2.2: DR grade (0-4 scale, APTOS); Topic 2.3: C/D ratio (Cup-to-Disc Ratio) or suspected-glaucoma classification</td></tr><tr><td><strong>Suggested dataset</strong></td><td>APTOS 2019 Blindness Detection (Kaggle) for 2.2; REFUGE Challenge or RIM-ONE for 2.3</td></tr><tr><td><strong>Mandatory requirement</strong></td><td><strong>Grad-CAM</strong> must highlight microaneurysms/hemorrhages (2.2) or the optic disc/cup boundary (2.3) — a &quot;black-box&quot; model without XAI <strong>does not pass</strong> the criteria (see warning below)</td></tr></tbody></table><hr><h2 id="_2-starter-literature-3-include-1-exclude-—-an-important-lesson" tabindex="-1">2. Starter literature (3 INCLUDE + 1 EXCLUDE — an important lesson) <a class="header-anchor" href="#_2-starter-literature-3-include-1-exclude-—-an-important-lesson" aria-label="Permalink to &quot;2. Starter literature (3 INCLUDE + 1 EXCLUDE — an important lesson)&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">The most important lesson of this review pass</p><p><code>sharma2025hybridglaucoma</code> (npj Digital Medicine 2025) has an extremely large scale (~50,000+ images) and very strong metrics (AUC 0.9567 internal / 0.9253 real-world) — <strong>the most impressive numbers among all 4 papers</strong>. But when verified in full text: the paper <strong>uses no Grad-CAM/SHAP/saliency map at all</strong> — it only outputs geometric parameters as &quot;interpretability&quot;. This topic&#39;s exclusion criteria clearly state <em>&quot;No XAI integration = excluded&quot;</em>. → <strong>EXCLUDE, despite having more impressive numbers than all 3 INCLUDE papers combined.</strong></p><p>This is a concrete demonstration: reading only the abstract, it would be very easy to wrongly include this paper. It only becomes clear when carefully reading the methods section to check the ACTUAL mandatory criterion (XAI) — not just looking at attractive outcome numbers.</p></div><table tabindex="0"><thead><tr><th>Citekey</th><th style="text-align:center;">Year</th><th>DOI</th><th>Summary</th></tr></thead><tbody><tr><td><code>ikram2025resvit</code></td><td style="text-align:center;">2025</td><td><em>(see <code>references.bib</code>)</em></td><td>ResNet50+ViT hybrid, APTOS 2019 (N=5,590), LIME+Grad-CAM, accuracy 93.01%</td></tr><tr><td><code>hemelings2021glaucoma</code></td><td style="text-align:center;">2021</td><td><em>(see <code>references.bib</code>)</em></td><td>CNN glaucoma + saliency map (iNNvestigate), <strong>has real external validation</strong> (REFUGE: AUC 0.87 external vs 0.94 internal UZL N=13,551) — a good example for students learning to design external validation</td></tr><tr><td><code>sharma2025multimodeldr</code></td><td style="text-align:center;">2025</td><td><em>(see <code>references.bib</code>)</em></td><td>Modified U-Net + Grad-CAM, Dice/IoU (DiaRetDB1: 0.9054/0.8272) + sensitivity/specificity across 3 datasets</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Beware overly perfect metrics — <code>sharma2025multimodeldr</code></p><p>Near-perfect metrics (accuracy 98.99–99.12%, sensitivity/specificity &gt;98.4/99.4% across <strong>all 3 independent datasets</strong>) are highly unusual for the DR-grading task — a red flag for overfitting/data leakage (the DiaRetDB1 set has only 89 original images yet train/test totals 705/303, suggesting heavy augmentation). <strong>The student team should treat this as a case-study exercise</strong>: read the full text and assess for yourselves whether the results are trustworthy before using them as a comparison baseline.</p></div><h3 id="prisma-diagram" tabindex="-1">PRISMA diagram <a class="header-anchor" href="#prisma-diagram" aria-label="Permalink to &quot;PRISMA diagram&quot;">​</a></h3>',13)),(t(),l(m,null,{default:r(()=>[c(o,{id:"mermaid-154",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A5%5B%22WebSearch%20%2B%20Crossref%20verify%3A%204%22%5D%20--%3E%20TOTAL_ID%5B%22Total%20records%3Cbr%3EN%20%3D%204%22%5D%0A%20%20%20%20TOTAL_ID%20--%3E%20EXCLUDED%5B%22EXCLUDE%20(missing%20mandatory%20XAI)%3A%3Cbr%3Esharma2025hybridglaucoma%20%E2%80%94%201%22%5D%0A%20%20%20%20TOTAL_ID%20--%3E%20FINAL_INC%5B%22INCLUDE%20into%20Evidence%20Matrix%3Cbr%3EN%20%3D%203%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_3-workflow-timeline" tabindex="-1">3. Workflow &amp; Timeline <a class="header-anchor" href="#_3-workflow-timeline" aria-label="Permalink to &quot;3. Workflow &amp; Timeline&quot;">​</a></h2><p>Follow the common 7-stage workflow / 15-week timeline (see the detailed template at <a href="/hmyt-book/en/du_an/roi_loan_nhip_tim">Topic 1.2 — Arrhythmia</a>). Medical-imaging-specific notes:</p><ul><li><strong>gd2-dataset-eda:</strong> visualize the disease-severity distribution (usually heavily imbalanced — mostly NORM/mild images), check image quality (blur, poor lighting).</li><li><strong>gd3-preprocessing:</strong> CLAHE/histogram equalization, crop the region of interest (ROI), augmentation (rotate/flip/crop — <strong>do not</strong> augment in ways that produce clinically unrealistic fake images). <strong>Patient/eye-level split is mandatory</strong> — one patient has 2 eyes, never let both images of the same patient land in both Train and Test.</li><li><strong>gd4/gd5:</strong> a plain ResNet-18 baseline before trying more complex architectures (DenseNet/EfficientNet/U-Net).</li><li><strong>gd6-evaluation-xai:</strong> <strong>Grad-CAM is mandatory</strong>, cross-checked against real anatomical regions (microaneurysms, hemorrhages, optic disc/cup) — learning from the <code>sharma2025hybridglaucoma</code> lesson above, XAI is not optional.</li></ul><hr><h2 id="_4-open-items-from-the-literature-report" tabindex="-1">4. Open items (from the literature report) <a class="header-anchor" href="#_4-open-items-from-the-literature-report" aria-label="Permalink to &quot;4. Open items (from the literature report)&quot;">​</a></h2><ol><li><strong>High priority:</strong> re-verify the full text of <code>sharma2025multimodeldr</code> before using it as official quantitative evidence.</li><li>The initial search scope was small (4 manually-found records) while this topic actually has MANY related publications — students should invest more time searching to reach ≥10 quality papers.</li></ol><div class="warning custom-block"><p class="custom-block-title">Zero-Hallucination</p><p>Every citation must match a real key in <code>.bib</code> with a DOI verified via the Crossref API.</p></div>',8))])}const D=i(u,[["render",h]]);export{v as __pageData,D as default};
